package io.github.classgraph;

import java.lang.annotation.Annotation;
import java.lang.reflect.Modifier;

import org.jspecify.annotations.Nullable;

/**
 * Holds metadata about class members of a class encountered during a scan. All values are taken directly out of the
 * classfile for the class.
 */
public abstract class ClassMemberInfo extends ScanResultObject implements HasName {
    /** Defining class name. */
    String declaringClassName;

    /** The name of the class member. */
    String name;

    /** Class member modifiers. */
    int modifiers;

    /** The JVM-internal type descriptor. */
    String typeDescriptorStr;

    /** The type signature. */
    @Nullable
    String typeSignatureStr;

    /** The annotation metadata for this class member. */
    @Nullable
    AnnotationInfoList annotationInfo;

    /** Annotation metadata access and query facade. */
    private final ClassMemberInfoAnnotations annotations;

    ClassMemberInfo(final String definingClassName, final String memberName, final int modifiers,
            final String typeDescriptorStr, final @Nullable String typeSignatureStr,
            final @Nullable AnnotationInfoList annotationInfo) {
        super();
        this.declaringClassName = definingClassName;
        this.name = memberName;
        this.modifiers = modifiers;
        this.typeDescriptorStr = typeDescriptorStr;
        this.typeSignatureStr = typeSignatureStr;
        this.annotationInfo = annotationInfo;
        this.annotations = new ClassMemberInfoAnnotations(this, annotationInfo);
    }

    @Override
    public @Nullable ClassInfo getClassInfo() {
        return super.getClassInfo();
    }

    @Override
    public String getClassName() {
        return declaringClassName;
    }

    @Override
    public String getName() {
        return name;
    }

    public int getModifiers() {
        return modifiers;
    }

    public abstract String getModifiersString();

    public boolean isPublic() {
        return Modifier.isPublic(modifiers);
    }

    public boolean isPrivate() {
        return Modifier.isPrivate(modifiers);
    }

    public boolean isProtected() {
        return Modifier.isProtected(modifiers);
    }

    public boolean isStatic() {
        return Modifier.isStatic(modifiers);
    }

    public boolean isFinal() {
        return Modifier.isFinal(modifiers);
    }

    public boolean isSynthetic() {
        return (modifiers & 0x1000) != 0;
    }

    public abstract @Nullable HierarchicalTypeSignature getTypeDescriptor();

    public String getTypeDescriptorString() {
        return typeDescriptorStr;
    }

    public abstract @Nullable HierarchicalTypeSignature getTypeSignature();

    public @Nullable String getTypeSignatureString() {
        return typeSignatureStr;
    }

    public abstract @Nullable HierarchicalTypeSignature getTypeSignatureOrTypeDescriptor();

    public String getTypeSignatureOrTypeDescriptorString() {
        return typeSignatureStr != null ? typeSignatureStr : typeDescriptorStr;
    }

    public AnnotationInfoList getAllAnnotationInfo() {
        return annotations.getAllAnnotationInfo();
    }

    public AnnotationInfoList getDirectAnnotationInfo() {
        return annotations.getDirectAnnotationInfo();
    }

    public @Nullable AnnotationInfo getAllAnnotationInfo(final Class<? extends Annotation> annotation) {
        return annotations.getAllAnnotationInfo(annotation);
    }

    public @Nullable AnnotationInfo getAllAnnotationInfo(final String annotationName) {
        return annotations.getAllAnnotationInfo(annotationName);
    }

    public @Nullable AnnotationInfo getDirectAnnotationInfo(final Class<? extends Annotation> annotation) {
        return annotations.getDirectAnnotationInfo(annotation);
    }

    public @Nullable AnnotationInfo getDirectAnnotationInfo(final String annotationName) {
        return annotations.getDirectAnnotationInfo(annotationName);
    }

    public AnnotationInfoList getAllAnnotationInfoRepeatable(final Class<? extends Annotation> annotation) {
        return annotations.getAllAnnotationInfoRepeatable(annotation);
    }

    public AnnotationInfoList getAllAnnotationInfoRepeatable(final String annotationName) {
        return annotations.getAllAnnotationInfoRepeatable(annotationName);
    }

    public AnnotationInfoList getDirectAnnotationInfoRepeatable(final Class<? extends Annotation> annotation) {
        return annotations.getDirectAnnotationInfoRepeatable(annotation);
    }

    public AnnotationInfoList getDirectAnnotationInfoRepeatable(final String annotationName) {
        return annotations.getDirectAnnotationInfoRepeatable(annotationName);
    }

    public boolean hasAnnotation(final Class<? extends Annotation> annotation) {
        return annotations.hasAnnotation(annotation);
    }

    public boolean hasAnnotation(final String annotationName) {
        return annotations.hasAnnotation(annotationName);
    }
}
